30	interface RouterMountLayer {
31	  name: "router";
32	  handle: CfRouter;
33	  regexp: RegExp;
34	  keys: unknown[];
35	}
36	
37	type StackLayer = RouteLayer | RouterMountLayer;
38	
39	export interface CfRouter {
40	  stack: StackLayer[];
41	  get(path: string, ...fns: MiddlewareFn[]): this;
42	  post(path: string, ...fns: MiddlewareFn[]): this;
43	  patch(path: string, ...fns: MiddlewareFn[]): this;
44	  put(path: string, ...fns: MiddlewareFn[]): this;
45	  delete(path: string, ...fns: MiddlewareFn[]): this;
46	  use(prefix: string | CfRouter, ...rest: CfRouter[]): this;
47	}
48	
49	function buildRouteLayer(method: string, path: string, fns: MiddlewareFn[]): RouteLayer {
50	  return {
51	    route: {
52	      path,
53	      methods: { [method]: true },
54	      stack: fns.map((handle) => ({ handle })),
55	    },
56	  };
57	}
58	
59	function prefixToRegexp(prefix: string): RegExp {
60	  // Mirror the regexp format Express produces for app.use('/prefix', router):
61	  //   /^\\/prefix\/?(?=\/|$)/i
62	  // express-router-bridge.ts reverses this via extractPathFromLayerRegexp.
63	  const escaped = prefix.replace(/\//g, "\\/");
64	  return new RegExp(`^\${escaped}\\/?(?=\\/|$)`, "i");
65	}
66	
67	function createRouter(): CfRouter {
68	  const router: CfRouter = {
69	    stack: [],
70	    get(path, ...fns) { this.stack.push(buildRouteLayer("get", path, fns)); return this; },
71	    post(path, ...fns) { this.stack.push(buildRouteLayer("post", path, fns)); return this; },
72	    patch(path, ...fns) { this.stack.push(buildRouteLayer("patch", path, fns)); return this; },
73	    put(path, ...fns) { this.stack.push(buildRouteLayer("put", path, fns)); return this; },
74	    delete(path, ...fns) { this.stack.push(buildRouteLayer("delete", path, fns)); return this; },
75	    use(prefix, ...rest) {
76	      if (typeof prefix === "string") {
77	        for (const nested of rest) {
78	          router.stack.push({
79	            name: "router",
80	            handle: nested,
81	            regexp: prefixToRegexp(prefix),
82	            keys: [],
83	          });
84	        }
85	      } else {
86	        // router.use(nestedRouter) — no prefix
87	        router.stack.push({
88	          name: "router",
89	          handle: prefix,
90	          regexp: prefixToRegexp(""),
91	          keys: [],
92	        });
93	      }
94	      return this;
95	    },
96	  };
97	  return router;
98	}
99	
100	// Default export matches express's export shape as used in the route files:
101	//   import { Router } from "express"
102	export const Router = createRouter;
103	
104	// Type-only re-exports so TypeScript is satisfied when route files do
105	//   import type { Request, Response, NextFunction } from "express"
106	// (type-only imports are erased at compile time, so no stubs needed)
107	export type Request = Record<string, unknown>;
108	export type Response = Record<string, unknown>;
109	export type NextFunction = () => void;
110	export type RequestHandler = MiddlewareFn;
