1	/**
2	 * CfCompanySkillsService — Cloudflare Workers implementation of the skill
3	 * bundle storage layer.
4	 *
5	 * Background (from company-skills.ts):
6	 *   The Node server stores skill files in a local directory tree on the host
7	 *   filesystem: walkLocalFiles / collectLocalSkillInventory traverse that tree,
8	 *   readFile reads SKILL.md and supporting files at request time, and
9	 *   createLocalSkill / updateFile write Markdown to disk.
10	 *   materializeCatalogSkillFiles / materializeRuntimeSkillFiles copy skill
11	 *   files into runtime-materialised directories.
12	 *
13	 * Workers replacement strategy:
14	 *   - File content lives in R2, keyed as `skills/{companyId}/{skillId}/{relativePath}`.
15	 *   - Skill metadata (name, description, version, sourceType, trustLevel, …)
16	 *     is read from the database via the caller's db handle (D1 or Hyperdrive).
17	 *   - Local-path skills referencing host directories are not supported in a
18	 *     stateless Worker deployment; those are delegated to the sidecar via
19	 *     SidecarClient.getSkillBundle().
20	 *   - Live validation and skill execution are always delegated to the sidecar.
21	 *
22	 * Key data types (from company-skills.ts):
23	 *   CompanySkillFileDetail  — { path, size, language, content, editable, … }
24	 *   CompanySkillDetail      — extends CompanySkillListItem with a files array
25	 *   fileInventory           — JSON column on the DB row listing known paths
26	 *
27	 * All code here is Web-API-only — no Node imports.
28	 */
29	
30	import type { SidecarClient } from "../sidecar-client.js";
31	
32	// ---------------------------------------------------------------------------
33	// R2 key helpers
34	// ---------------------------------------------------------------------------
35	
36	function skillPrefix(companyId: string, skillId: string): string {
37	  return `skills/${companyId}/${skillId}/`;
38	}
39	
40	function skillKey(companyId: string, skillId: string, relativePath: string): string {
41	  return `${skillPrefix(companyId, skillId)}${relativePath}`;
42	}
43	
44	// ---------------------------------------------------------------------------
45	// Service
46	// ---------------------------------------------------------------------------
47	
48	export class CfCompanySkillsService {
49	  constructor(
50	    private r2: R2Bucket,
51	    private sidecar: SidecarClient,
52	  ) {}
53	
54	  // -------------------------------------------------------------------------
55	  // Bundle read — assembles { files } from R2 objects
56	  //
57	  // Iterates all R2 objects under the skill prefix (mirrors walkLocalFiles) and
58	  // fetches each body in parallel. Falls back to the sidecar for source types
59	  // that require the host filesystem (local_path, catalog with live sync).
60	  // -------------------------------------------------------------------------
61	
62	  async getSkillBundle(
63	    companyId: string,
64	    skillId: string,
65	  ): Promise<{ files: Record<string, string> }> {
66	    const prefix = skillPrefix(companyId, skillId);
67	    const list = await this.r2.list({ prefix });
68	
69	    if (list.objects.length === 0) {
70	      // Nothing in R2 — ask the sidecar (covers local_path / catalog sources).
71	      return this.sidecar.getSkillBundle(companyId, skillId);
72	    }
73	
74	    // Fetch all file bodies in parallel to keep latency low.
75	    const entries = await Promise.all(
76	      list.objects.map(async (obj) => {
77	        const result = await this.r2.get(obj.key);
78	        const content = result ? await result.text() : "";
79	        const relativePath = obj.key.replace(prefix, "");
80	        return [relativePath, content] as const;
81	      }),
82	    );
83	
84	    return { files: Object.fromEntries(entries) };
85	  }
86	
87	  // -------------------------------------------------------------------------
88	  // Single file read — mirrors readFile in company-skills.ts
89	  // -------------------------------------------------------------------------
90	
91	  async getSkillFile(
92	    companyId: string,
93	    skillId: string,
94	    relativePath: string,
95	  ): Promise<string | null> {
96	    const result = await this.r2.get(skillKey(companyId, skillId, relativePath));
97	    return result ? result.text() : null;
98	  }
99	
100	  // -------------------------------------------------------------------------
101	  // Write — mirrors createLocalSkill / updateFile in company-skills.ts
102	  // -------------------------------------------------------------------------
103	
104	  async putSkillFile(
105	    companyId: string,
106	    skillId: string,
107	    relativePath: string,
108	    content: string,
109	  ): Promise<void> {
110	    await this.r2.put(skillKey(companyId, skillId, relativePath), content, {
111	      httpMetadata: { contentType: "text/plain" },
112	    });
113	  }
114	
115	  // -------------------------------------------------------------------------
116	  // List — mirrors walkLocalFiles / collectLocalSkillInventory for managed skills
117	  // -------------------------------------------------------------------------
118	
119	  async listSkillFiles(companyId: string, skillId: string): Promise<string[]> {
120	    const prefix = skillPrefix(companyId, skillId);
121	    const list = await this.r2.list({ prefix });
122	    return list.objects.map((obj) => obj.key.replace(prefix, ""));
123	  }
124	
125	  // -------------------------------------------------------------------------
126	  // Delete — mirrors the rm calls made during skill deletion in company-skills.ts
127	  // -------------------------------------------------------------------------
128	
129	  async deleteSkillBundle(companyId: string, skillId: string): Promise<void> {
130	    const prefix = skillPrefix(companyId, skillId);
131	    const list = await this.r2.list({ prefix });
132	
133	    // Delete objects sequentially to avoid R2 rate limits on large bundles.
134	    for (const obj of list.objects) {
135	      await this.r2.delete(obj.key);
136	    }
137	  }
138	}
