812	
813	    if (!packageName || typeof packageName !== "string") {
814	      return Response.json({ error: "packageName is required and must be a string" }, { status: 400 });
815	    }
816	
817	    if (version !== undefined && typeof version !== "string") {
818	      return Response.json({ error: "version must be a string if provided" }, { status: 400 });
819	    }
820	
821	    if (isLocalPath !== undefined && typeof isLocalPath !== "boolean") {
822	      return Response.json({ error: "isLocalPath must be a boolean if provided" }, { status: 400 });
823	    }
824	
825	    const trimmedPackage = packageName.trim();
826	    if (trimmedPackage.length === 0) {
827	      return Response.json({ error: "packageName cannot be empty" }, { status: 400 });
828	    }
829	
830	    if (!isLocalPath && /[<>:"|?*]/.test(trimmedPackage)) {
831	      return Response.json({ error: "packageName contains invalid characters" }, { status: 400 });
832	    }
833	
834	    try {
835	      const installOptions = isLocalPath
836	        ? { localPath: trimmedPackage }
837	        : { packageName: trimmedPackage, version: version?.trim() };
838	
839	      const discovered = await loader.installPlugin(installOptions);
840	
841	      if (!discovered.manifest) {
