37	import { goalRoutes } from "../../../../server/src/routes/goals.js";
38	import { approvalRoutes } from "../../../../server/src/routes/approvals.js";
39	import { secretRoutes } from "../../../../server/src/routes/secrets.js";
40	import { costRoutes } from "../../../../server/src/routes/costs.js";
