51	// ---------------------------------------------------------------------------
52	// Types
53	// ---------------------------------------------------------------------------
54	
55	export interface CompiledRoute {
56	  route: RouteDefinition;
57	  re: RegExp;
58	  paramNames: string[];
59	}
60	
61	export interface RequestResources {
62	  compiled: CompiledRoute[];
63	  db: Db;
64	  storage: StorageService;
65	}
66	
67	// ---------------------------------------------------------------------------
68	// Path pattern compilation
69	// ---------------------------------------------------------------------------
70	
71	// Cached route path patterns. These are stateless (no DB reference) and safe
72	// to reuse across requests within the same isolate.
73	let compiledPathCache: Array<{ re: RegExp; paramNames: string[] }> | null = null;
74	
75	/** Converts an Express-style path (with :param segments) to a RegExp + param names. */
76	function pathToRegex(path: string): { re: RegExp; paramNames: string[] } {
77	  const paramNames: string[] = [];
78	  const pattern = path
79	    .replace(/[$()*+.?[\\\]^{|}]/g, "\\$&")
80	    .replace(/:([a-zA-Z_][a-zA-Z0-9_]*)/g, (_match, name: string) => {
81	      paramNames.push(name);
82	      return "([^/]+)";
83	    });
84	  return { re: new RegExp(`^${pattern}$`), paramNames };
85	}
86	
87	function ext(router: unknown, prefix: string): RouteDefinition[] {
88	  return extractRoutesFromRouter(router, prefix);
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Per-request resource builder
93	// ---------------------------------------------------------------------------
94	
95	/**
96	 * Builds a fresh DB instance, storage provider, and route handler closures
97	 * for the current request.
98	 *
99	 * Call once per request (not at module load time) because:
100	 *   - The Drizzle DB wraps a postgres-js pool backed by a Hyperdrive TCP
101	 *     connection that CF Workers prohibits reusing across requests.
102	 *   - Route handler closures capture `db` and `storage`, so they must be
103	 *     rebuilt whenever the DB instance is replaced.
104	 *
105	 * Route path regexps are compiled once and reused via `compiledPathCache`.
106	 */
107	export function buildRequestResources(env: Env): RequestResources {
108	  const db = createHyperdriveDb(env.HYPERDRIVE);
109	  const r2Provider = new R2Provider(env.PAPERCLIP_STORAGE, {
110	    bucket: env.STORAGE_R2_BUCKET ?? "paperclip-storage",
111	    prefix: env.STORAGE_R2_PREFIX ?? "",
112	  });
113	  const storage = createCfStorageService(r2Provider) as unknown as StorageService;
114	
115	  const routes: RouteDefinition[] = [
116	    ...ext(companyRoutes(db, storage), "/api/companies"),
117	    ...ext(agentRoutes(db, {}), "/api"),
118	    ...ext(assetRoutes(db, storage), "/api"),
119	    ...ext(projectRoutes(db), "/api"),
120	    ...ext(issueRoutes(db, storage, {}), "/api"),
121	    ...ext(issueTreeControlRoutes(db), "/api"),
122	    ...ext(routineRoutes(db, {}), "/api"),
123	    ...ext(environmentRoutes(db, {}), "/api"),
124	    ...ext(executionWorkspaceRoutes(db), "/api"),
125	    ...ext(goalRoutes(db), "/api"),
126	    ...ext(approvalRoutes(db, {}), "/api"),
127	    ...ext(secretRoutes(db), "/api"),
128	    ...ext(costRoutes(db, {}), "/api"),
129	    ...ext(activityRoutes(db), "/api"),
130	    ...ext(dashboardRoutes(db), "/api"),
131	    ...ext(userProfileRoutes(db), "/api"),
132	    ...ext(sidebarBadgeRoutes(db), "/api"),
133	    ...ext(sidebarPreferenceRoutes(db), "/api"),
134	    ...ext(inboxDismissalRoutes(db), "/api"),
135	    ...ext(instanceSettingsRoutes(db), "/api"),
136	    ...ext(llmRoutes(db), "/api"),
137	    ...ext(authRoutes(db), "/api/auth"),
138	    // Access routes use raw Express handlers — use the CF bridge to capture all of them
139	    ...extractAllRoutesFromRouter(
140	      accessRoutes(db, {
141	        deploymentMode: resolveDeploymentMode(env),
142	        deploymentExposure: (env.DEPLOYMENT_EXPOSURE ?? "private") as "private" | "public",
143	        bindHost: "",
144	        allowedHostnames: [],
145	      }),
146	      "/api",
147	    ),
148	  ];
149	
150	  if (!compiledPathCache) {
151	    compiledPathCache = routes.map((r) => pathToRegex(r.path));
152	    console.log(`[CF Worker] Compiled ${compiledPathCache.length} route patterns`);
153	  }
154	
155	  const compiled: CompiledRoute[] = routes.map((route, i) => ({
156	    route,
157	    re: compiledPathCache![i]!.re,
158	    paramNames: compiledPathCache![i]!.paramNames,
159	  }));
160	
161	  return { compiled, db, storage };
162	}
