3	 *
4	 * This file is intentionally thin: it wires together the Hono app,
5	 * queue consumer, and cron handlers, then re-exports named Durable Object
6	 * and Workflow classes so Wrangler can register them.
7	 *
8	 * Routes skipped (use Node-only features — left as 501 TODOs):
9	 *   - adapterRoutes           reads packages from disk
10	 *   - pluginRoutes            SSE, child processes, scoped plugin API
11	 *   - pluginUiStaticRoutes    fs.readFileSync / res.sendFile
12	 *   - companySkillRoutes      local filesystem (CF version: cf-company-skills.ts)
13	 *   - accessRoutes            reads bundled SKILL.md files from disk
14	 *   - instanceDatabaseBackupRoutes  pg_dump
15	 *
16	 * Architecture note on per-request DB injection:
17	 *   Route handlers capture a `db` reference via service factory closures.
18	 *   Because Hyperdrive connections cannot be reused across CF Workers requests,
19	 *   we rebuild the DB + route handlers on every request. Route path regexps
20	 *   are static and are cached at module level in route-registry.ts.
21	 */
22	
23	import { bootCloudflare } from "../boot.js";
24	import { app } from "./app.js";
25	import { createHyperdriveDb } from "../db/hyperdrive.js";
26	import { runHeartbeatSweep } from "../cron/heartbeat-sweep.js";
27	import type { Env } from "./env.js";
28	
29	// Re-export Env so other modules (e.g. heartbeat-sweep) can import it from here.
30	export type { Env };
31	
32	// ---------------------------------------------------------------------------
33	// Workers fetch handler
34	// ---------------------------------------------------------------------------
35	
36	export default {
37	  fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
38	    // Boot CF implementations (idempotent — safe to call on every request).
39	    bootCloudflare(env);
40	    return app.fetch(request, env, ctx);
41	  },
42	
43	  // -------------------------------------------------------------------------
44	  // Queues consumer
45	  // -------------------------------------------------------------------------
46	  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
47	    for (const message of batch.messages) {
48	      const body = message.body as Record<string, unknown>;
49	      const type = body?.type as string | undefined;
50	
51	      if (type === "plugin_job_dispatch") {
52	        const pluginJobId = body.pluginJobId as string;
53	        const pluginSlug = body.pluginSlug as string;
54	        const companyId = body.companyId as string;
55	        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";
56	        try {
57	          await env.PLUGIN_DISPATCH_WORKFLOW.create({
58	            id: `plugin-job-${pluginJobId}`,
59	            params: { pluginJobId, pluginSlug, companyId, executorMode },
60	          });
61	          message.ack();
62	        } catch (err) {
63	          console.error(`[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${err instanceof Error ? err.message : String(err)}`);
64	          message.retry();
65	        }
66	        continue;
67	      }
68	
69	      if (type === "heartbeat_dispatch") {
70	        const agentId = body.agentId as string;
71	        const companyId = body.companyId as string;
72	        const runId = body.runId as string;
73	        const taskId = body.taskId as string | undefined;
74	        try {
75	          await env.HEARTBEAT_WORKFLOW.create({
76	            id: `heartbeat-${runId}`,
77	            params: { agentId, companyId, runId, taskId },
78	          });
79	          message.ack();
80	        } catch (err) {
81	          console.error(`[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${err instanceof Error ? err.message : String(err)}`);
82	          message.retry();
83	        }
84	        continue;
85	      }
86	
87	      console.warn(`[Queue] Unknown message type: ${type ?? "(none)"}`);
88	      message.ack();
89	    }
90	  },
91	
92	  // -------------------------------------------------------------------------
93	  // Cron triggers
94	  // -------------------------------------------------------------------------
95	  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
96	    if (event.cron === "*/5 * * * *") {
97	      const db = createHyperdriveDb(env.HYPERDRIVE);
98	      await runHeartbeatSweep(env, db);
99	      return;
100	    }
101	    // "0 * * * *"  — budget threshold check (not yet implemented)
102	    // "0 3 * * *"  — DB backup (not yet implemented)
103	  },
104	};
105	
106	// ---------------------------------------------------------------------------
107	// Named Durable Object + Workflow exports
108	// Wrangler requires these to be named exports from the Worker's main module.
109	// ---------------------------------------------------------------------------
110	
111	export { TaskDO } from "../runtime/task-do.js";
112	export { AgentRunDO } from "../runtime/agent-run-do.js";
113	export { SchedulerDO } from "../scheduler/scheduler-do.js";
114	export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
115	export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";
