3	/**
4	 * Parameters passed when triggering the HeartbeatWorkflow.
5	 */
6	export interface HeartbeatParams {
7	  /** The agent whose heartbeat is being executed. */
8	  agentId: string;
9	  /** Company the agent belongs to (used for scoped DB queries). */
10	  companyId: string;
11	  /** Unique identifier for this specific heartbeat run. */
12	  runId: string;
13	  /**
14	   * Optional task (issue) the agent is currently working on.
15	   * May be absent if the agent has no active checkout.
16	   */
17	  taskId?: string;
18	}
19	
20	/**
21	 * Env bindings required by the HeartbeatWorkflow.
22	 * Keep in sync with `src/worker/api.ts#Env`.
23	 */
24	interface Env {
25	  AGENT_RUN_DO: DurableObjectNamespace;
26	  TASK_DO: DurableObjectNamespace;
27	  HYPERDRIVE: { connectionString: string };
28	  PAPERCLIP_KV: KVNamespace;
29	  // TODO: add SANDBOX_BRIDGE_URL and SANDBOX_BRIDGE_API_KEY secrets
30	}
31	
32	/**
33	 * HeartbeatWorkflow — Cloudflare Workflow that executes one agent heartbeat.
34	 *
35	 * A heartbeat is the fundamental unit of agent work in Paperclip: the agent
36	 * is woken up, runs an LLM turn (potentially using tools), and records the
37	 * outcome. The Workflow wraps this in durable, checkpointed steps so that a
38	 * Worker crash or timeout does not lose progress.
39	 *
40	 * Steps:
41	 *   1. init-run      — Create the AgentRunDO record; mark run as "running".
42	 *   2. execute       — Call the sandbox bridge to run the actual heartbeat.
43	 *                      Retries up to 2 times with a 5-second delay on failure.
44	 *   3. record-result — Update the AgentRunDO with the final outcome; notify
45	 *                      the TaskDO so connected UIs receive a state update.
46	 *
47	 * The Workflow is triggered by the SchedulerDO alarm handler or the
48	 * `POST /api/agents/:agentId/wakeup` endpoint.
49	 *
50	 * Idempotency: `runId` is unique per invocation. Cloudflare Workflows
51	 * guarantee each step runs at most once per `runId`; duplicate triggers
52	 * are deduplicated by the Workflow engine using the instance ID.
53	 */
54	export class HeartbeatWorkflow extends WorkflowEntrypoint<Env, HeartbeatParams> {
55	  async run(event: WorkflowEvent<HeartbeatParams>, step: WorkflowStep): Promise<void> {
56	    const { agentId, companyId, runId, taskId } = event.payload;
57	
58	    // ------------------------------------------------------------------
59	    // Step 1: Initialise the run record and mark it as running
60	    // ------------------------------------------------------------------
61	    await step.do("init-run", async () => {
62	      const id = this.env.AGENT_RUN_DO.idFromName(runId);
63	      const stub = this.env.AGENT_RUN_DO.get(id);
64	
65	      // Initialise the run document in the DO
66	      const initResp = await stub.fetch("http://internal/init", {
67	        method: "POST",
68	        headers: { "Content-Type": "application/json" },
69	        body: JSON.stringify({
70	          runId,
71	          agentId,
72	          companyId,
73	          taskId,
74	          status: "running",
75	          startedAt: new Date().toISOString(),
76	          logCount: 0,
77	        }),
78	      });
79	      if (!initResp.ok) {
80	        throw new Error(`AgentRunDO init failed: HTTP ${initResp.status}`);
81	      }
82	
83	      // If there is an associated task, update the TaskDO so the UI reflects
84	      // that a heartbeat is now running.
85	      if (taskId) {
86	        const taskId_ = this.env.TASK_DO.idFromName(taskId);
87	        const taskStub = this.env.TASK_DO.get(taskId_);
88	        await taskStub.fetch("http://internal/state", {
89	          method: "POST",
90	          headers: { "Content-Type": "application/json" },
91	          body: JSON.stringify({
92	            taskId,
93	            status: "running",
94	            currentStep: "heartbeat",
95	            updatedAt: new Date().toISOString(),
96	          }),
97	        });
98	      }
99	    });
100	
101	    // ------------------------------------------------------------------
102	    // Step 2: Execute the heartbeat via the sandbox bridge
103	    // ------------------------------------------------------------------
104	    const executeResult = await step.do(
105	      "execute",
106	      {
107	        timeout: "5 minutes",
108	        retries: { limit: 2, delay: "5 seconds", backoff: "linear" },
109	      },
110	      async () => {
111	        // TODO: replace with the actual internal heartbeat API URL once
112	        // the HTTP adapter migration (PR #6/#7) lands. For now we call a
113	        // placeholder endpoint on the main Worker.
114	        const bridgeUrl =
115	          (await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_URL")) ??
116	          "http://localhost:8788";
117	        const apiKey = await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_API_KEY");
118	
119	        const resp = await fetch(`${bridgeUrl}/internal/heartbeat`, {
120	          method: "POST",
121	          headers: {
122	            "Content-Type": "application/json",
123	            ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
124	          },
125	          body: JSON.stringify({ agentId, companyId, runId, taskId }),
126	        });
127	
128	        if (!resp.ok) {
129	          const body = await resp.text().catch(() => "(unreadable)");
130	          throw new Error(`Heartbeat execution failed: HTTP ${resp.status}: ${body}`);
131	        }
132	
133	        return (await resp.json()) as { status: string; liveness?: string };
134	      },
135	    );
136	
137	    // ------------------------------------------------------------------
138	    // Step 3: Record the result in AgentRunDO and notify TaskDO
139	    // ------------------------------------------------------------------
140	    await step.do("record-result", async () => {
141	      const id = this.env.AGENT_RUN_DO.idFromName(runId);
142	      const stub = this.env.AGENT_RUN_DO.get(id);
143	
144	      const succeeded = executeResult?.status !== "failed";
145	      await stub.fetch("http://internal/state", {
146	        method: "POST",
147	        headers: { "Content-Type": "application/json" },
148	        body: JSON.stringify({
149	          status: succeeded ? "succeeded" : "failed",
150	          completedAt: new Date().toISOString(),
151	        }),
152	      });
153	
154	      // Update TaskDO so the UI reflects the completed heartbeat
155	      if (taskId) {
156	        const taskId_ = this.env.TASK_DO.idFromName(taskId);
157	        const taskStub = this.env.TASK_DO.get(taskId_);
158	        await taskStub.fetch("http://internal/state", {
159	          method: "POST",
160	          headers: { "Content-Type": "application/json" },
161	          body: JSON.stringify({
162	            taskId,
163	            status: succeeded ? "running" : "failed",
164	            currentStep: "idle",
165	            updatedAt: new Date().toISOString(),
166	          }),
167	        });
168	      }
169	    });
170	  }
171	}
