1	import { WorkflowEntrypoint, type WorkflowStep, type WorkflowEvent } from "cloudflare:workers";
2	
3	/**
4	 * Parameters for the PluginDispatchWorkflow.
5	 */
6	export interface PluginDispatchParams {
7	  /** The `plugin_jobs.id` primary key of the job to execute. */
8	  pluginJobId: string;
9	  /** Plugin slug — used for routing to the correct executor config. */
10	  pluginSlug: string;
11	  /** Company context. */
12	  companyId: string;
13	  /**
14	   * Executor mode: `sandbox_bridge` (default) routes to the existing E2B/SSH
15	   * sandbox bridge; `container` uses a Cloudflare Container binding.
16	   */
17	  executorMode: "sandbox_bridge" | "container";
18	}
19	
20	/**
21	 * Env bindings required by the PluginDispatchWorkflow.
22	 */
23	interface Env {
24	  AGENT_RUN_DO: DurableObjectNamespace;
25	  PAPERCLIP_KV: KVNamespace;
26	  // TODO: PLUGIN_CONTAINER_SERVICE binding (Fetcher) for container executor mode
27	}
28	
29	/**
30	 * PluginDispatchWorkflow — Cloudflare Workflow that executes one plugin job.
31	 *
32	 * Plugin jobs are discrete units of work enqueued by the plugin job scheduler
33	 * (replaced by a Cloudflare Queue consumer on CF deployments). Each job has a
34	 * `plugin_jobs` record in the database. The Workflow:
35	 *
36	 *   1. Marks the job as "running" via the internal API.
37	 *   2. Dispatches execution to the configured executor (sandbox bridge or
38	 *      Cloudflare Container), with timeout and retry semantics.
39	 *   3. Records the outcome — success or failure — via the internal API.
40	 *
41	 * Retries up to 2 times on transient executor failures before marking the
42	 * job as permanently failed.
43	 *
44	 * Triggered by the Cloudflare Queue consumer in `api.ts` when a
45	 * `plugin_job_dispatch` message arrives on `paperclip-jobs`.
46	 */
47	export class PluginDispatchWorkflow extends WorkflowEntrypoint<Env, PluginDispatchParams> {
48	  async run(event: WorkflowEvent<PluginDispatchParams>, step: WorkflowStep): Promise<void> {
49	    const { pluginJobId, pluginSlug, companyId, executorMode } = event.payload;
50	
51	    // ------------------------------------------------------------------
52	    // Step 1: Claim the job — mark it as running to prevent duplicate dispatch
53	    // ------------------------------------------------------------------
54	    const claimed = await step.do("claim-job", async () => {
55	      // TODO: call the internal plugin job claim endpoint once the HTTP
56	      // adapter migration (PR #6/#7) lands.
57	      const bridgeUrl =
58	        (await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_URL")) ??
59	        "http://localhost:8788";
60	      const apiKey = await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_API_KEY");
61	
62	      const resp = await fetch(`${bridgeUrl}/internal/plugin-jobs/${pluginJobId}/claim`, {
63	        method: "POST",
64	        headers: {
65	          "Content-Type": "application/json",
66	          ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
67	        },
68	        body: JSON.stringify({ companyId }),
69	      });
70	
71	      if (resp.status === 409) {
72	        // Already claimed by another worker — skip this invocation
73	        return { claimed: false };
74	      }
75	      if (!resp.ok) {
76	        throw new Error(`Claim failed: HTTP ${resp.status}`);
77	      }
78	      return { claimed: true };
79	    });
80	
81	    if (!claimed.claimed) {
82	      // Another invocation already owns this job; exit cleanly
83	      return;
84	    }
85	
86	    // ------------------------------------------------------------------
87	    // Step 2: Execute the plugin job
88	    // ------------------------------------------------------------------
89	    const executionResult = await step.do(
90	      "execute-job",
91	      {
92	        timeout: "10 minutes",
93	        retries: { limit: 2, delay: "10 seconds", backoff: "exponential" },
94	      },
95	      async () => {
96	        const bridgeUrl =
97	          (await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_URL")) ??
98	          "http://localhost:8788";
99	        const apiKey = await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_API_KEY");
100	
101	        let executionEndpoint: string;
102	        if (executorMode === "container") {
103	          // TODO: route to Cloudflare Container service binding
104	          // executionEndpoint = `http://container/plugin-jobs/${pluginJobId}/execute`;
105	          executionEndpoint = `${bridgeUrl}/internal/plugin-jobs/${pluginJobId}/execute`;
106	        } else {
107	          executionEndpoint = `${bridgeUrl}/internal/plugin-jobs/${pluginJobId}/execute`;
108	        }
109	
110	        const resp = await fetch(executionEndpoint, {
111	          method: "POST",
112	          headers: {
113	            "Content-Type": "application/json",
114	            ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
115	          },
116	          body: JSON.stringify({ pluginJobId, pluginSlug, companyId }),
117	        });
118	
119	        if (!resp.ok) {
120	          const body = await resp.text().catch(() => "(unreadable)");
121	          throw new Error(`Plugin job execution failed: HTTP ${resp.status}: ${body}`);
122	        }
123	
124	        return (await resp.json()) as { status: string; exitCode?: number };
125	      },
126	    );
127	
128	    // ------------------------------------------------------------------
129	    // Step 3: Record the result
130	    // ------------------------------------------------------------------
131	    await step.do("record-result", async () => {
132	      const bridgeUrl =
133	        (await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_URL")) ??
134	        "http://localhost:8788";
135	      const apiKey = await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_API_KEY");
