1	/**
2	 * Cloudflare Worker environment bindings and deployment-mode helpers.
3	 *
4	 * Keeping `Env` in its own file lets every worker sub-module import it
5	 * without pulling in the full Hono app or route registry.
6	 */
7	
8	// ---------------------------------------------------------------------------
9	// Env -- Cloudflare bindings injected at runtime by the Workers runtime
10	// ---------------------------------------------------------------------------
11	
12	export interface Env {
13	  // Databases
14	  HYPERDRIVE: { connectionString: string };
15	
16	  // Object storage
17	  PAPERCLIP_STORAGE: R2Bucket;
18	
19	  // KV -- setup flags, hot config, session cache
20	  PAPERCLIP_KV: KVNamespace;
21	
22	  // Durable Object namespaces
23	  TASK_DO: DurableObjectNamespace;
24	  AGENT_RUN_DO: DurableObjectNamespace;
25	  SCHEDULER_DO: DurableObjectNamespace;
26	
27	  // Queues
28	  PAPERCLIP_QUEUE: Queue;
29	
30	  // Workflows
31	  HEARTBEAT_WORKFLOW: Workflow;
32	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
33	
34	  // Vars (set in wrangler.toml [vars] or .dev.vars for local dev)
35	  DEPLOYMENT_PLATFORM: string;
36	  DEPLOYMENT_MODE: string;
37	  DEPLOYMENT_EXPOSURE: string;
38	  STORAGE_R2_BUCKET?: string;
39	  STORAGE_R2_PREFIX?: string;
40	
41	  // Container DO namespaces — each wraps a CF Container that starts a Docker
42	  // image and proxies HTTP to it.  In local dev the DO falls back to
43	  // SIDECAR_URL (env var) or SANDBOX_BRIDGE_URL (KV) for its requests.
44	  SIDECAR_SERVICE?: DurableObjectNamespace;   // companion Node server
45	  PLUGIN_CONTAINER?: DurableObjectNamespace;  // isolated command executor
46	
47	  // Direct sidecar URL — used by SidecarContainer as fallback when no Docker
48	  // container is running (local dev).  Set in .dev.vars or via wrangler secret.
49	  SIDECAR_URL?: string;
50	  SIDECAR_API_KEY?: string;
51	
52	  // Static assets binding — serves ui/dist alongside the Worker.
53	  // Use env.ASSETS.fetch(request) to serve static files or let CF fall
54	  // back to index.html for SPA routes (not_found_handling = "single-page-application").
55	  ASSETS: Fetcher;
56	}
57	
58	// ---------------------------------------------------------------------------
59	// Deployment mode
60	// ---------------------------------------------------------------------------
61	
62	export type DeploymentMode = "local_trusted" | "authenticated";
63	
64	/**
