// ---------------------------------------------------------------------------
// Low-level routing primitive
// ---------------------------------------------------------------------------

/**
 * Route and call the sidecar: use the SIDECAR_SERVICE DO when available,
 * otherwise fall back to a direct HTTP URL.
 *
 * The caller is responsible for resolving `url` and `apiKey` from env vars or
 * KV before calling (so KV reads don't get retried alongside the actual call).
 * Returns `null` when no route is available (service absent AND url is null).
 */
export interface SidecarRouting {
  /** CF Container DO namespace — preferred path. */
  service?: DurableObjectNamespace | null;
  /** Direct fallback URL (already resolved from env var or KV). */
  url?: string | null;
  /** API key for the direct URL path. */
  apiKey?: string | null;
}

export async function callSidecarService(
  routing: SidecarRouting,
  path: string,
  method: string,
  body?: unknown,
): Promise<Response | null> {
  const headers: Record<string, string> = {};
  if (body !== undefined) headers["Content-Type"] = "application/json";

  if (routing.service) {
    const stub = routing.service.get(routing.service.idFromName("sidecar"));
    return stub.fetch(`http://sidecar${path}`, {
      method,
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });
  }

  if (!routing.url) return null;

  if (routing.apiKey) headers.Authorization = `Bearer ${routing.apiKey}`;
  return fetch(`${routing.url}${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
}

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

export interface SidecarConfig {

const bridgeUrl = this.env.SIDECAR_SERVICE
  ? null
  : ((await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_URL")) ?? "http://localhost:8788");
const apiKey = this.env.SIDECAR_SERVICE
  ? null
  : await this.env.PAPERCLIP_KV.get("SANDBOX_BRIDGE_API_KEY");

const resp = await callSidecarService(
  { service: this.env.SIDECAR_SERVICE, url: bridgeUrl, apiKey },
  "/internal/heartbeat",
  "POST",
  { agentId, companyId, runId, taskId },
);
if (!resp) throw new Error("No sidecar route available: configure SIDECAR_SERVICE or SANDBOX_BRIDGE_URL");
if (!resp.ok) {
  const text = await resp.text().catch(() => "(unreadable)");
  throw new Error(`Heartbeat execution failed: HTTP ${resp.status}: ${text}`);
}

