1	/**
2	 * routes/plugins.ts
3	 *
4	 * CF-native handlers for:
5	 *   GET /api/plugins
6	 *   GET /api/plugins/ui-contributions
7	 *   GET /api/plugins/examples
8	 *   POST /api/plugins/install
9	 *
10	 * The server-side pluginRoutes() relies on an in-process plugin registry
11	 * (worker processes, SSE, child_process) that does not exist in a CF Worker.
12	 * These handlers derive the same data from the `plugins` DB table, which is
13	 * populated at install time and is always available via Hyperdrive.
14	 *
15	 * install / examples notes:
16	 *   Plugin installation requires npm access and is delegated to the sidecar
17	 *   companion server (SidecarContainer DO or SIDECAR_URL env var).
18	 *   Examples are returned with localPath = packageName so the UI issues an
19	 *   npm install rather than a local-filesystem install.
20	 *
21	 * Auth: requires an authenticated actor (board or agent). Unauthenticated
22	 * requests receive 401.
23	 */
24	
25	import type { Hono } from "hono";
26	import { asc, ne } from "drizzle-orm";
27	import { plugins } from "@paperclipai/db";
28	import { getPluginUiContributionMetadata } from "../../../../../server/src/services/plugin-loader.js";
29	import { createHyperdriveDb } from "../../db/hyperdrive.js";
30	import { resolveActorFromRequest } from "../../auth/resolve-actor.js";
31	import { resolveDeploymentMode } from "../env.js";
32	import type { Env } from "../env.js";
33	
34	
35	/** Proxy a request to the sidecar companion server.
36	 *
37	 * Security: caller Authorization headers are stripped. The SIDECAR_SERVICE DO
38	 * uses internal CF network auth; direct SIDECAR_URL calls use SIDECAR_API_KEY.
39	 */
40	async function proxySidecar(env: Env, path: string, req: Request): Promise<Response> {
41	  const ct = req.headers.get("Content-Type");
42	  const internalHeaders = new Headers();
43	  if (ct) internalHeaders.set("Content-Type", ct);
44	
45	  if (env.SIDECAR_SERVICE) {
46	    const stub = env.SIDECAR_SERVICE.get(env.SIDECAR_SERVICE.idFromName("sidecar"));
47	    return stub.fetch(`http://sidecar${path}`, {
48	      method: req.method,
49	      headers: internalHeaders,
50	      body: req.body,
51	    });
52	  }
53	  const baseUrl = env.SIDECAR_URL;
54	  if (!baseUrl) {
55	    return Response.json(
56	      { error: "Plugin install not available: configure SIDECAR_URL or SIDECAR_SERVICE" },
57	      { status: 503 },
58	    );
59	  }
60	  if (env.SIDECAR_API_KEY) internalHeaders.set("Authorization", `Bearer ${env.SIDECAR_API_KEY}`);
61	  return fetch(`${baseUrl}${path}`, { method: req.method, headers: internalHeaders, body: req.body });
62	}
63	
64	export function registerPluginRoutes(app: Hono<{ Bindings: Env }>): void {
65	  // -------------------------------------------------------------------------
66	  // GET /api/plugins — list installed plugins from DB (registry state comes
67	  // from manifestJson stored at install time; worker processes not available)
68	  // -------------------------------------------------------------------------
69	  app.get("/api/plugins", async (c) => {
70	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
71	    const actor = await resolveActorFromRequest(c.req.raw, db, {
72	      deploymentMode: resolveDeploymentMode(c.env),
73	    });
74	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
75	
76	    const rows = await db
77	      .select()
78	      .from(plugins)
79	      .where(ne(plugins.status, "uninstalled"))
80	      .orderBy(asc(plugins.installOrder));
81	    return c.json(rows);
82	  });
83	
84	  // -------------------------------------------------------------------------
85	  // GET /api/plugins/ui-contributions — derive UI contribution metadata from
86	  // manifestJson stored in the DB (no running plugin process needed).
87	  // Must be registered before /api/plugins so Hono matches it first.
88	  // -------------------------------------------------------------------------
89	  app.get("/api/plugins/ui-contributions", async (c) => {
90	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
91	    const actor = await resolveActorFromRequest(c.req.raw, db, {
92	      deploymentMode: resolveDeploymentMode(c.env),
93	    });
94	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
95	
96	    const rows = await db
97	      .select()
98	      .from(plugins)
99	      .where(ne(plugins.status, "uninstalled"))
100	      .orderBy(asc(plugins.installOrder));
101	
102	    const contributions = rows.flatMap((plugin) => {
103	      const manifest = plugin.manifestJson;
104	      if (!manifest) return [];
105	      const uiMetadata = getPluginUiContributionMetadata(manifest);
106	      if (!uiMetadata) return [];
107	      return [{
108	        pluginId: plugin.id,
109	        pluginKey: plugin.pluginKey,
110	        displayName: manifest.displayName,
111	        version: plugin.version,
112	        updatedAt: plugin.updatedAt.toISOString(),
113	        uiEntryFile: uiMetadata.uiEntryFile,
114	        slots: uiMetadata.slots,
115	        launchers: uiMetadata.launchers,
116	      }];
117	    });
118	    return c.json(contributions);
119	  });
120	
121	  // -------------------------------------------------------------------------
122	  // GET /api/plugins/examples — proxy to sidecar.
123	  // The sidecar runs the server's listBundledPluginExamples() which checks
124	  // whether local monorepo paths exist and returns them with absolute paths.
125	  // In local dev the monorepo IS present so examples appear; in production
126	  // the sidecar container has a different filesystem and returns [].
127	  // -------------------------------------------------------------------------
128	  app.get("/api/plugins/examples", async (c) => {
129	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
130	    const actor = await resolveActorFromRequest(c.req.raw, db, {
131	      deploymentMode: resolveDeploymentMode(c.env),
132	    });
133	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
134	
135	    try {
136	      const resp = await proxySidecar(c.env, "/api/plugins/examples", c.req.raw);
137	      if (!resp.ok) return c.json([]);
138	      return new Response(resp.body, { status: resp.status, headers: { "Content-Type": "application/json" } });
139	    } catch {
140	      // Sidecar unreachable (not running locally) — return empty list.
141	      return c.json([]);
142	    }
143	  });
144	
145	  // -------------------------------------------------------------------------
146	  // POST /api/plugins/install — delegate to sidecar (needs npm + filesystem).
147	  // The sidecar installs the package, registers it in the DB, and returns the
148	  // plugin record. localPath values equal to a package name are treated as
149	  // npm installs by the sidecar's install handler.
150	  // -------------------------------------------------------------------------
151	  app.post("/api/plugins/install", async (c) => {
152	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
153	    const actor = await resolveActorFromRequest(c.req.raw, db, {
154	      deploymentMode: resolveDeploymentMode(c.env),
155	    });
156	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
157	
158	    // CF has no local filesystem, so isLocalPath is never meaningful here.
159	    // If the UI sent isLocalPath: true with an npm package name (e.g. from
160	    // the examples list), rewrite the body to use npm install semantics.
161	    const body = await c.req.json<{ packageName?: string; version?: string; isLocalPath?: boolean }>();
162	    const isNpmPackage = !body.isLocalPath || !body.packageName?.startsWith("/");
163	    const rewritten = isNpmPackage
164	      ? { packageName: body.packageName, version: body.version, isLocalPath: false }
165	      : body;
166	
167	    try {
168	      const resp = await proxySidecar(c.env, "/api/plugins/install",
169	        new Request(c.req.url, {
170	          method: "POST",
171	          headers: { "Content-Type": "application/json" },
172	          body: JSON.stringify(rewritten),
173	        }),
174	      );
175	      return new Response(resp.body, { status: resp.status, headers: { "Content-Type": "application/json" } });
176	    } catch {
177	      return c.json(
178	        { error: "Plugin install requires the Node.js server to be running (pnpm dev or bun run dev)" },
179	        503,
180	      );
181	    }
182	  });
183	}
