describe("CF Worker smoke — agent-scoped reads (regression: URL-key resolution)", () => {
  const routes = [
    "",
    "configuration",
    "config-revisions",
    "runtime-state",
    "task-sessions",
    "skills",
    "instructions-bundle",
    "keys",
  ];

  for (const tail of routes) {
    it(`GET /api/agents/:uuid${tail ? "/" + tail : ""}`, async () => {
      if (!agent) return;
      const path = `/api/agents/${agent.id}${tail ? "/" + tail : ""}`;
      const r = await get(path);
