async function normalizeAgentReference(ctx: RequestCtx, rawId: string): Promise<string> {
  const raw = rawId.trim();
  if (isUuidLike(raw)) return raw;

  const companyId = await resolveCompanyIdForAgentReference(ctx);
  if (!companyId) {
